#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
use eframe::egui::{self, Color32, RichText};
mod presence;
mod sound;
mod personality;
mod hardware;
mod model_manager;
mod autostart;
mod memory_core;
use serde::{Serialize, Deserialize};
use std::{sync::mpsc, io::{BufRead, BufReader}, time::Duration};
use rusqlite::{Connection, params};
#[derive(Clone, Serialize, Deserialize)]
struct Message { role: String, content: String }
#[derive(Clone, Serialize, Deserialize)]
#[serde(default)]
struct Config { model: String, traits: [u8;7], mode: String, english: bool, avatar: bool, minimize_to_tray: bool, dark: bool, sound: bool, volume: u8, setup_complete: bool }
impl Default for Config { fn default()->Self { Self { model:"qwen2.5:3b".into(), traits:[90,80,90,90,90,80,70], mode:"Companion".into(), english:false, avatar:true, minimize_to_tray:true, dark:true, sound:true, volume:35, setup_complete:false } } }
const TRAITS:[&str;7]=["Аналітичність","Емпатія","Допитливість","Гумор","Ініціативність","Емоційність","Сарказм"];
const EN:[&str;7]=["Analysis","Empathy","Curiosity","Humor","Initiative","Emotion","Sarcasm"];
enum Event { Token(String), Done, Error(String), Models(Vec<String>), ModelError(String), Hardware(Result<hardware::Hardware,String>), PullProgress(String,Option<f32>), PullDone(Result<(),String>) }
struct App { presence: presence::Presence, db: Option<Connection>, config:Config, messages:Vec<Message>, memories:Vec<String>, input:String, memory:String, status:String, page:usize, tx:mpsc::Sender<Event>, rx:mpsc::Receiver<Event>, busy:bool, draft:String, models:Vec<String>, model_status:String, hardware:Option<hardware::Hardware>, hardware_status:String, pulling:bool, pull_status:String, pull_progress:Option<f32>, autostart:bool, memory_search:String }
impl App {
fn new(cc:&eframe::CreationContext<'_>)->Self {
 let mut visuals=egui::Visuals::dark(); visuals.panel_fill=Color32::from_rgb(12,18,25); visuals.selection.bg_fill=Color32::from_rgb(22,95,99); cc.egui_ctx.set_visuals(visuals);
 let dir=std::env::var_os("LOCALAPPDATA").map(std::path::PathBuf::from).unwrap_or_else(||std::path::PathBuf::from(".")).join("HATORI_AI");
 let db=std::fs::create_dir_all(&dir).and_then(|_| Ok(())).ok().and_then(|_|Connection::open(dir.join("memory.sqlite3")).ok()).filter(|d|d.execute_batch("CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY, role TEXT, content TEXT); CREATE TABLE IF NOT EXISTS memories(id INTEGER PRIMARY KEY, content TEXT); CREATE TABLE IF NOT EXISTS config(id INTEGER PRIMARY KEY, value TEXT);").is_ok());
 let mut config=Config::default(); let mut messages=vec![]; let mut memories=vec![];
 if let Some(d)=&db { if let Ok(s)=d.query_row("SELECT value FROM config WHERE id=1",[],|r|r.get::<_,String>(0)){config=serde_json::from_str(&s).unwrap_or_default();} if let Ok(mut q)=d.prepare("SELECT role,content FROM messages ORDER BY id") { if let Ok(rows)=q.query_map([],|r|Ok(Message{role:r.get(0)?,content:r.get(1)?})){messages=rows.filter_map(Result::ok).collect();} } if let Ok(mut q)=d.prepare("SELECT content FROM memories ORDER BY id") {if let Ok(rows)=q.query_map([],|r|r.get::<_,String>(0)){memories=rows.filter_map(Result::ok).collect();}} }
 let status=if db.is_some(){"Ready / local storage"}else{"Storage unavailable — session only"}.into(); let(tx,rx)=mpsc::channel(); let initial_page=if config.setup_complete {0}else{4}; let app=Self{presence:presence::Presence::new(),db,config,messages,memories,input:String::new(),memory:String::new(),status,page:initial_page,tx,rx,busy:false,draft:String::new(),models:vec![],model_status:"Checking Ollama…".into(),hardware:None,hardware_status:"Scanning…".into(),pulling:false,pull_status:String::new(),pull_progress:None,autostart:autostart::enabled(),memory_search:String::new()}; app.refresh(); let tx=app.tx.clone(); std::thread::spawn(move||{let _=tx.send(Event::Hardware(hardware::scan()));}); app
}
fn save(&mut self){if let Some(d)=&self.db {if let Err(e)=d.execute("INSERT OR REPLACE INTO config VALUES(1,?1)",[serde_json::to_string(&self.config).unwrap_or_default()]){self.status=e.to_string();}}}
fn add(&mut self,role:&str,content:String){if let Some(d)=&self.db{if let Err(e)=d.execute("INSERT INTO messages(role,content) VALUES(?1,?2)",params![role,&content]){self.status=e.to_string();}} self.messages.push(Message{role:role.into(),content});}
fn send(&mut self){if self.busy||self.input.trim().is_empty(){return;} let input=std::mem::take(&mut self.input); let relevant=memory_core::relevant(&input,&self.memories); self.add("user",input); self.busy=true; self.draft.clear(); self.status="Generating…".into(); let tx=self.tx.clone(); let cfg=self.config.clone(); let mut messages=vec![Message{role:"system".into(),content:personality::prompt(&cfg.mode,cfg.traits,&relevant)}]; messages.extend(self.messages.iter().rev().take(16).cloned().collect::<Vec<_>>().into_iter().rev());
 std::thread::spawn(move||{let result=(||->Result<(),Box<dyn std::error::Error>>{let client=reqwest::blocking::Client::builder().connect_timeout(Duration::from_secs(4)).timeout(Duration::from_secs(300)).build()?; let response=client.post("http://127.0.0.1:11434/api/chat").json(&serde_json::json!({"model":cfg.model,"messages":messages,"stream":true})).send()?.error_for_status()?; for line in BufReader::new(response).lines(){let v:serde_json::Value=serde_json::from_str(&line?)?; if let Some(e)=v["error"].as_str(){return Err(e.to_owned().into());} if let Some(s)=v["message"]["content"].as_str(){let _=tx.send(Event::Token(s.into()));} if v["done"].as_bool()==Some(true){return Ok(());}} Err("Stream ended prematurely".into())})(); let _=tx.send(match result{Ok(())=>Event::Done,Err(e)=>Event::Error(e.to_string())});});
}
fn pull(&mut self){if self.pulling||self.busy||self.config.model.trim().is_empty(){return;} self.pulling=true;self.pull_progress=None;self.pull_status="Connecting…".into();let model=self.config.model.trim().to_owned();let tx=self.tx.clone();std::thread::spawn(move||{let result=model_manager::pull(&model,|status,progress|{let _=tx.send(Event::PullProgress(status,progress));}).map_err(|e|e.to_string());let _=tx.send(Event::PullDone(result));});}
fn refresh(&self){let tx=self.tx.clone(); std::thread::spawn(move||{let result=(||->Result<Vec<String>,Box<dyn std::error::Error>>{let v:serde_json::Value=reqwest::blocking::Client::builder().timeout(Duration::from_secs(5)).build()?.get("http://127.0.0.1:11434/api/tags").send()?.error_for_status()?.json()?; Ok(v["models"].as_array().into_iter().flatten().filter_map(|m|m["name"].as_str().map(str::to_owned)).collect())})();let _=tx.send(match result{Ok(m)=>Event::Models(m),Err(e)=>Event::ModelError(e.to_string())});});}
}
impl eframe::App for App {fn update(&mut self,ctx:&egui::Context,_:&mut eframe::Frame){
 if ctx.style().visuals.dark_mode != self.config.dark {ctx.set_visuals(if self.config.dark {egui::Visuals::dark()} else {egui::Visuals::light()});}
 while let Ok(e)=self.rx.try_recv(){match e{Event::PullProgress(status,progress)=>{self.pull_status=status;self.pull_progress=progress;},Event::PullDone(result)=>{self.pulling=false;match result{Ok(())=>{self.pull_status="Download complete".into();self.pull_progress=Some(1.0);self.refresh();},Err(e)=>{self.pull_status=format!("Download failed: {e}");self.pull_progress=None;}}},Event::Hardware(result)=>{match result{Ok(h)=>{self.hardware=Some(h);self.hardware_status="Ready".into();},Err(e)=>self.hardware_status=e}},Event::Token(t)=>{if self.config.sound && !t.trim().is_empty(){sound::tick(self.config.volume);} self.draft.push_str(&t)},Event::Done=>{self.busy=false;let s=std::mem::take(&mut self.draft);self.add("assistant",s);self.status="Ready".into();},Event::Error(e)=>{self.busy=false;self.status=format!("Ollama: {e}. Перевірте ollama list та ollama serve.");},Event::ModelError(e)=>{self.model_status=format!("Ollama unavailable: {e}");},Event::Models(m)=>{self.models=m;self.model_status=if self.models.is_empty(){"Ollama connected; no models installed".into()}else{"Ollama connected".into()};}}}
 if self.presence.update(ctx, &mut self.config, self.busy) { self.save(); }
 ctx.request_repaint_after(Duration::from_millis(100)); let en=self.config.english; let accent=Color32::from_rgb(92,228,213);
 egui::TopBottomPanel::top("header").show(ctx,|ui|{ui.horizontal(|ui|{ui.heading(RichText::new("H A T O R I  /  AI").color(accent));ui.label(concat!("GENESIS ",env!("CARGO_PKG_VERSION")));ui.separator();ui.label(&self.status);});});
 egui::SidePanel::left("nav").default_width(205.).show(ctx,|ui|{let (r,_)=ui.allocate_exact_size(egui::vec2(180.,180.),egui::Sense::hover());let p=ui.painter();let c=r.center();let t=ctx.input(|i|i.time) as f32;for k in 0..3{p.circle_stroke(c,42.+k as f32*15.,egui::Stroke::new(1.,accent.gamma_multiply(0.5)));}let points=(0..6).map(|i|{let a=t*0.3+i as f32*std::f32::consts::TAU/6.;c+egui::vec2(a.cos(),a.sin())*48.}).collect();p.add(egui::Shape::closed_line(points,egui::Stroke::new(2.,accent)));p.circle_filled(c,10.+(t*3.).sin()*3.,accent);ui.label(if self.busy{"PROCESSING"}else{"STANDBY"});ui.separator();let labels=if en{["Chat","Memory","Personality","Models","Setup"]}else{["Діалог","Пам'ять","Особистість","Моделі","Налаштування"]};for (i,l) in labels.iter().enumerate(){ui.selectable_value(&mut self.page,i,*l);}if ui.checkbox(&mut self.config.english,"English").changed(){self.save();} ui.separator(); if ui.checkbox(&mut self.config.dark,"Темна тема / Dark").changed(){self.save();} if ui.checkbox(&mut self.config.sound,"8-bit sound").changed(){self.save();} if ui.add(egui::Slider::new(&mut self.config.volume,0..=100).text("Volume")).changed(){self.save();} if ui.checkbox(&mut self.config.avatar, "Desktop avatar").changed(){self.save();} if ui.checkbox(&mut self.config.minimize_to_tray, "Minimize to tray").changed(){self.save();} if cfg!(windows) && ui.checkbox(&mut self.autostart,if en{"Start with Windows"}else{"Запускати з Windows"}).changed(){if let Err(e)=autostart::set(self.autostart){self.status=e;self.autostart=autostart::enabled();}} if let Some(e)=&self.presence.error {ui.label(e);} if self.presence.available() && ui.button("Hide to tray").clicked(){self.presence.hide(ctx);}});
 egui::CentralPanel::default().show(ctx,|ui|{match self.page{0=>{egui::ComboBox::from_id_salt("mode").selected_text(&self.config.mode).show_ui(ui,|ui|{for m in ["Companion","Assistant","Developer","Researcher"]{ui.selectable_value(&mut self.config.mode,m.into(),m);}});ui.add_enabled_ui(!self.busy,|ui|{if ui.button(if en{"Save mode"}else{"Зберегти режим"}).clicked(){self.save();}});egui::TopBottomPanel::bottom("compose").show_inside(ui,|ui|{let id=ui.make_persistent_id("compose_input"); let enter=!self.busy && ui.memory(|m|m.has_focus(id)) && ui.input_mut(|i|i.consume_key(egui::Modifiers::NONE,egui::Key::Enter)); ui.add(egui::TextEdit::multiline(&mut self.input).id(id).desired_rows(3).desired_width(f32::INFINITY));if enter || ui.add_enabled(!self.busy,egui::Button::new(if en{"Send"}else{"Надіслати"})).clicked(){self.send();}});egui::ScrollArea::vertical().stick_to_bottom(true).show(ui,|ui|{for m in &self.messages{ui.label(RichText::new(if m.role=="user"{"YOU"}else{"HATORI"}).color(accent));ui.label(&m.content);ui.separator();}if !self.draft.is_empty(){ui.label(&self.draft);}});},1=>{ui.heading(if en{"Approved memories"}else{"Затверджені спогади"});ui.text_edit_multiline(&mut self.memory);if ui.button(if en{"Add memory"}else{"Додати спогад"}).clicked()&&!self.memory.trim().is_empty(){let s=std::mem::take(&mut self.memory);if let Some(d)=&self.db{if let Err(e)=d.execute("INSERT INTO memories(content) VALUES(?1)",[&s]){self.status=e.to_string();}}self.memories.push(s);}ui.label(if en{"Search memories"}else{"Пошук спогадів"});ui.text_edit_singleline(&mut self.memory_search);let mut remove=None;egui::ScrollArea::vertical().show(ui,|ui|{for (i,m) in self.memories.iter().enumerate(){if !m.to_lowercase().contains(&self.memory_search.to_lowercase()){continue;}ui.label(m);if ui.button(if en{"Delete"}else{"Видалити"}).clicked(){remove=Some(i);}ui.separator();}});if let Some(i)=remove{let m=&self.memories[i];let result=self.db.as_ref().map(|d|d.execute("DELETE FROM memories WHERE id=(SELECT id FROM memories WHERE content=?1 ORDER BY id LIMIT 1)",[m]));match result{Some(Err(e))=>self.status=e.to_string(),_=>{self.memories.remove(i);}}}},2=>{ui.heading("Personality / 001");for i in 0..7{ui.add(egui::Slider::new(&mut self.config.traits[i],0..=100).text(if en{EN[i]}else{TRAITS[i]}));}if ui.button("Save / Зберегти").clicked(){self.save();}},4=>{ui.heading(if en{"Welcome to HATORI"}else{"Вітаю! Я HATORI."});ui.label(if en{"Local setup — choose your model and language."}else{"Локальне налаштування — обери модель та мову."});ui.checkbox(&mut self.config.english,"English");ui.separator();ui.label(&self.hardware_status);ui.label(&self.model_status);if let Some(h)=&self.hardware{let recommended=hardware::recommend(h.ram_gib);ui.label(format!("RAM-based recommendation: {recommended}"));if ui.button(if en{"Use recommendation"}else{"Обрати рекомендовану"}).clicked(){self.config.model=recommended.into();}}ui.text_edit_singleline(&mut self.config.model);let installed=self.models.iter().any(|m|m==&self.config.model);if ui.button(if en{"Check connection"}else{"Перевірити підключення"}).clicked(){self.refresh();}if !installed{ui.label(if en{"Ollama must be installed and running. Download requires internet."}else{"Ollama має бути встановлена та запущена. Для завантаження потрібен інтернет."});if ui.add_enabled(!self.pulling&&!self.busy,egui::Button::new(if en{"Download model"}else{"Завантажити модель"})).clicked(){self.pull();}}ui.label(&self.pull_status);if let Some(p)=self.pull_progress{ui.add(egui::ProgressBar::new(p).show_percentage());}ui.separator();if ui.add_enabled(installed&&!self.pulling,egui::Button::new(if en{"Finish setup"}else{"Завершити налаштування"})).clicked(){self.config.setup_complete=true;self.save();self.page=0;}if ui.button(if en{"Skip for now"}else{"Пропустити поки що"}).clicked(){self.page=0;}},_=>{ui.heading(if en{"Hardware / recommended model"}else{"Обладнання / рекомендована модель"});ui.label(&self.hardware_status);if let Some(h)=&self.hardware{ui.label(&h.cpu);ui.label(format!("RAM: {:?}",h.ram_gib));for gpu in &h.gpus{ui.label(gpu);}let recommended=hardware::recommend(h.ram_gib);ui.label(format!("RAM-based estimate: {recommended}"));if ui.button("Select recommended model").clicked(){self.config.model=recommended.into();self.save();}}ui.separator();ui.heading("Ollama / localhost");ui.label("http://127.0.0.1:11434");ui.label(&self.model_status);ui.label(if self.models.iter().any(|m|m==&self.config.model){"Selected model available"}else{"Selected model not confirmed"});if ui.add_enabled(!self.busy,egui::Button::new("Refresh models")).clicked(){self.refresh();}ui.text_edit_singleline(&mut self.config.model);for m in &self.models{ui.selectable_value(&mut self.config.model,m.clone(),m);}if ui.button("Save").clicked(){self.save();}if ui.add_enabled(!self.pulling&&!self.busy,egui::Button::new(if en{"Download selected model"}else{"Завантажити обрану модель"})).clicked(){self.pull();}ui.label(&self.pull_status);if let Some(p)=self.pull_progress{ui.add(egui::ProgressBar::new(p).show_percentage());ui.label(if en{"Current layer progress"}else{"Прогрес поточного шару"});}}}});}}
fn main()->eframe::Result<()> {eframe::run_native("HATORI AI",eframe::NativeOptions{viewport:egui::ViewportBuilder::default().with_inner_size([1050.,720.]),..Default::default()},Box::new(|cc|Ok(Box::new(App::new(cc)))))}
